message.content:
{
  "title": "The Ruined City Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined city gates.",
      "visual_description": "Rusted iron gates loom under a stormy sky, broken statues flank the entrance, and old royal banners hang tattered from the walls.",
      "characters": ["Lyra the Healer", "Kael the Scout"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople whisper warnings in the shadows.",
      "visual_description": "Huddled figures in rags point toward the inner city, their faces pale and eyes wide with fear as they speak in hushed tones.",
      "characters": ["Lyra the Healer", "Kael the Scout", "Mira the Mage", "Townspeople"]
    },
    {
      "scene_number": 3,
      "caption": "The party passes under the castle gates.",
      "visual_description": "A massive portcullis partially raised, with iron spikes above and torchlight flickering from inside the courtyard.",
      "characters": ["Lyra the Healer", "Kael the Scout", "Mira the Mage", "Ren the Warrior"]
    },
    {
      "scene_number": 4,
      "caption": "Armored patrols march through the main square.",
      "visual_description": "Rows of soldiers in black armor stomp in unison, their shields bearing a serpent crest, scattering stray cats and debris.",
      "characters": ["Armored Patrol", "Lyra the Healer", "Kael the Scout"]
    },
    {
      "scene_number": 5,
      "caption": "The party hides in an abandoned bakery.",
      "visual_description": "Dusty shelves and a cold oven; cobwebs drape over broken bread molds; they peer through a cracked window at the patrol.",
      "characters": ["Lyra the Healer", "Kael the Scout", "Mira the Mage", "Ren the Warrior"]
    },
    {
      "scene_number": 6,
      "caption": "Rumors of a dragon reach the party from a beggar.",
      "visual_description": "A one-eyed beggar crouches by a fountain, his voice raspy as he speaks of a beast sleeping beneath the old tower.",
      "characters": ["Lyra the Healer", "Kael the Scout", "Beggar"]
    },
    {
      "scene_number": 7,
      "caption": "The cursed tower looms before them.",
      "visual_description": "A spiraling black stone tower wrapped in thorny vines, its top lost in mist, with faint green glow pulsing from narrow windows.",
      "characters": ["Lyra the Healer", "Kael the Scout", "Mira the Mage", "Ren the Warrior"]
    },
    {
      "scene_number": 8,
      "caption": "A magic door seals the tower entrance.",
      "visual_description": "A door of polished obsidian with runes that shift and rearrange, humming with arcane energy that repels touch.",
      "characters": ["Mira the Mage", "Lyra the Healer", "Ren the Warrior"]
    },
    {
      "scene_number": 9,
      "caption": "Mira deciphers the runes on the magic door.",
      "visual_description": "She traces the glowing symbols with her staff, her eyes reflecting the light as she mutters an incantation; the door groans.",
      "characters": ["Mira the Mage", "Lyra the Healer", "Kael the Scout", "Ren the Warrior"]
    },
    {
      "scene_number": 10,
      "caption": "Inside the tower, illusions tempt the party.",
      "visual_description": "Ghostly images of gold, feasts, and loved ones appear in the corridor, whispering promises; the floor is slippery with false treasure.",
      "characters": ["Lyra the Healer", "Kael the Scout", "Mira the Mage", "Ren the Warrior"]
    },
    {
      "scene_number": 11,
      "caption": "Ren breaks an illusion with his sword.",
      "visual_description": "He slashes through a shimmering mirage of a banquet, the vision shattering into sparks, revealing a hidden stairwell.",
      "characters": ["Ren the Warrior", "Lyra the Healer", "Kael the Scout", "Mira the Mage"]
    },
    {
      "scene_number": 12,
      "caption": "The party finds the prisoner in the tower's heart.",
      "visual_description": "A single cell at the tower's core, bars of black iron, and a young woman in chains, her eyes closed but alive.",
      "characters": ["Lyra the Healer", "Kael the Scout", "Mira the Mage", "Ren the Warrior", "Elara the Prisoner"]
    },
    {
      "scene_number": 13,
      "caption": "Lyra picks the lock on the cell.",
      "visual_description": "She kneels by the door, using a thin metal tool; sweat on her brow as the lock clicks open with a soft sound.",
      "characters": ["Lyra the Healer", "Elara the Prisoner"]
    },
    {
      "scene_number": 14,
      "caption": "The alarm is raised; guards rush the tower.",
      "visual_description": "Horns blare, heavy footsteps echo up the stairs, and torchlight flickers from below as armored men charge.",
      "characters": ["Armored Patrol", "Lyra the Healer", "Kael the Scout", "Mira the Mage", "Ren the Warrior", "Elara the Prisoner"]
    },
    {
      "scene_number": 15,
      "caption": "The party fights through the tower courtyard.",
      "visual_description": "Clashing swords and spells; Ren holds the line while Kael shoots arrows from behind a fountain; Mira throws firebolts.",
      "characters": ["Ren the Warrior", "Kael the Scout", "Mira the Mage", "Lyra the Healer", "Elara the Prisoner", "Armored Patrol"]
    },
    {
      "scene_number": 16,
      "caption": "They reach the bridge leading out of the city.",
      "visual_description": "A long stone bridge spanning a chasm, with crumbling parapets and the city gate on the far side; guards closing in behind.",
      "characters": ["Lyra the Healer", "Kael the Scout", "Mira the Mage", "Ren the Warrior", "Elara the Prisoner"]
    },
    {
      "scene_number": 17,
      "caption": "The bridge begins to collapse as they cross.",
      "visual_description": "Stones fall into the abyss, cracks spider across the span; Kael grabs Elara as a section crumbles behind them.",
      "characters": ["Kael the Scout", "Elara the Prisoner", "Lyra the Healer", "Mira the Mage", "Ren the Warrior"]
    },
    {
      "scene_number": 18,
      "caption": "The party escapes into the wilderness beyond.",
      "visual_description": "They stumble onto a grassy hillside, the ruined city in the distance, smoke rising; the sky clears as they catch their breath.",
      "characters": ["Lyra the Healer", "Kael the Scout", "Mira the Mage", "Ren the Warrior", "Elara the Prisoner"]
    }
  ]
}

